#[expect(dead_code, reason = "build support module shared with build.rs")]
#[path = "../../build_support/mod.rs"]
mod build_support;

use std::{
    fs,
    path::{Path, PathBuf},
    process::Command,
    time::{SystemTime, UNIX_EPOCH},
};

#[test]
fn manifest_parser_ignores_comments_and_blank_lines() {
    let directives = build_support::cmake::parse_cargo_link_directives(
        r#"
        # Generated by CMake.

        cargo:rustc-link-search=native=/tmp/cudf/lib
        cargo:rustc-link-lib=dylib=cudf_rust
        cargo:metadata=cuda-runtime=shared
        "#,
    )
    .unwrap();

    assert_eq!(
        directives,
        vec![
            "cargo:rustc-link-search=native=/tmp/cudf/lib",
            "cargo:rustc-link-lib=dylib=cudf_rust",
            "cargo:metadata=cuda-runtime=shared",
        ]
    );
}

#[test]
fn manifest_parser_rejects_non_cargo_lines() {
    let error = build_support::cmake::parse_cargo_link_directives(
        r#"
        cargo:rustc-link-lib=dylib=cudf_rust
        libcudf.so
        "#,
    )
    .unwrap_err();

    assert!(error.contains("line 3"), "unexpected error: {error}");
}

#[test]
fn read_cargo_link_directives_uses_expected_install_location() {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let install_prefix = std::env::temp_dir().join(format!("cudf-sys-build-link-contract-{unique}"));
    let manifest_path = build_support::cmake::cargo_link_manifest_path(&install_prefix);
    fs::create_dir_all(manifest_path.parent().unwrap()).unwrap();
    fs::write(&manifest_path, "cargo:rustc-link-search=native=/tmp/cudf/lib\ncargo:rustc-link-lib=dylib=cudf_rust\n")
        .unwrap();

    let directives = build_support::cmake::read_cargo_link_directives(&install_prefix).unwrap();

    assert_eq!(
        directives,
        vec!["cargo:rustc-link-search=native=/tmp/cudf/lib", "cargo:rustc-link-lib=dylib=cudf_rust",]
    );

    fs::remove_file(&manifest_path).unwrap();
    fs::remove_dir_all(&install_prefix).unwrap();
}

#[test]
fn parse_cmake_bool_normalizes_common_truthy_and_falsey_values() {
    for truthy in ["1", "on", "TRUE", "Yes"] {
        assert_eq!(build_support::cmake::parse_cmake_bool("CUDA_STATIC_RUNTIME", truthy).unwrap(), "ON");
    }

    for falsey in ["0", "off", "FALSE", "No"] {
        assert_eq!(build_support::cmake::parse_cmake_bool("CUDA_STATIC_RUNTIME", falsey).unwrap(), "OFF");
    }
}

#[test]
fn parse_cmake_bool_rejects_invalid_values() {
    let error = build_support::cmake::parse_cmake_bool("CUDA_STATIC_RUNTIME", "maybe").unwrap_err();
    assert!(error.contains("CUDA_STATIC_RUNTIME"), "unexpected error: {error}");
}

#[test]
fn cmake_cache_value_reads_typed_entries() {
    let cache = "CMAKE_INSTALL_PREFIX:PATH=/tmp/out\nCUDF_INSTALL_DIR:STRING=/opt/cudf\n";

    assert_eq!(build_support::cmake::cmake_cache_value(cache, "CMAKE_INSTALL_PREFIX"), Some("/tmp/out"));
    assert_eq!(build_support::cmake::cmake_cache_value(cache, "CUDF_INSTALL_DIR"), Some("/opt/cudf"));
    assert_eq!(build_support::cmake::cmake_cache_value(cache, "MISSING"), None);
}

#[test]
fn cached_cmake_compilers_reject_toolchain_transitions() {
    let cache = "\
CMAKE_C_COMPILER:FILEPATH=/opt/gcc-14/bin/gcc\n\
CMAKE_CXX_COMPILER:FILEPATH=/opt/gcc-14/bin/g++\n";

    assert!(build_support::cmake::cached_cmake_compilers_match(
        cache,
        Path::new("/opt/gcc-14/bin/gcc"),
        Path::new("/opt/gcc-14/bin/g++"),
    ));
    assert!(!build_support::cmake::cached_cmake_compilers_match(
        cache,
        Path::new("/usr/bin/cc"),
        Path::new("/usr/bin/c++"),
    ));

    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let temp_dir = std::env::temp_dir().join(format!("cudf-sys-compiler-cache-contract-{unique}"));
    let compiler = temp_dir.join("gcc-14");
    let compiler_symlink = temp_dir.join("cc");
    fs::create_dir_all(&temp_dir).unwrap();
    fs::write(&compiler, "").unwrap();
    std::os::unix::fs::symlink(&compiler, &compiler_symlink).unwrap();

    assert!(build_support::cmake::paths_equivalent(&compiler_symlink, &compiler));
    assert!(!build_support::cmake::cached_cmake_compilers_match(
        &format!(
            "CMAKE_C_COMPILER:FILEPATH={}\nCMAKE_CXX_COMPILER:FILEPATH={}\n",
            compiler_symlink.display(),
            compiler.display(),
        ),
        &compiler,
        &compiler,
    ));

    fs::remove_dir_all(temp_dir).unwrap();
}

#[test]
fn cached_cudf_discovery_matches_install_path_and_rejects_stale_paths() {
    let install_dir = Path::new("/opt/current-cudf");

    assert!(build_support::cmake::cached_cudf_discovery_matches(
        "CUDF_INSTALL_DIR:STRING=/opt/current-cudf\ncudf_DIR:PATH=/opt/current-cudf/lib/cmake/cudf\n",
        Some(install_dir),
        None,
    ));
    assert!(!build_support::cmake::cached_cudf_discovery_matches(
        "CUDF_INSTALL_DIR:STRING=/opt/old-cudf\n",
        Some(install_dir),
        None,
    ));
    assert!(!build_support::cmake::cached_cudf_discovery_matches(
        "CUDF_INSTALL_DIR:STRING=/opt/current-cudf\nCUDF_CPP_BUILD_DIR:STRING=/tmp/old-build\n",
        Some(install_dir),
        None,
    ));
}

#[test]
fn cached_cudf_discovery_matches_build_path_and_rejects_mode_switch_cache() {
    let build_dir = Path::new("/opt/cudf/cpp/build");

    assert!(build_support::cmake::cached_cudf_discovery_matches(
        "CUDF_CPP_BUILD_DIR:STRING=/opt/cudf/cpp/build\n",
        None,
        Some(build_dir),
    ));
    assert!(!build_support::cmake::cached_cudf_discovery_matches(
        "CUDF_CPP_BUILD_DIR:STRING=/opt/cudf/cpp/old\n",
        None,
        Some(build_dir),
    ));
    assert!(!build_support::cmake::cached_cudf_discovery_matches(
        "CUDF_INSTALL_DIR:STRING=/opt/old-install\nCUDF_CPP_BUILD_DIR:STRING=/opt/cudf/cpp/build\n",
        None,
        Some(build_dir),
    ));
}

#[test]
fn cached_cudf_discovery_defers_missing_paths_to_cmake_contract() {
    assert!(
        build_support::cmake::cached_cudf_discovery_matches("CUDF_INSTALL_DIR:STRING=/opt/old-cudf\n", None, None,)
    );
}

#[test]
fn libcudf_runtime_identity_prefers_installed_prefix_layout() {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let temp_dir = std::env::temp_dir().join(format!("cudf-sys-installed-libcudf-contract-{unique}"));
    let install_dir = temp_dir.join("install");
    let build_dir = temp_dir.join("build");
    let installed_libcudf = install_dir.join("lib/libcudf.so");
    let build_libcudf = build_dir.join("libcudf.so");
    fs::create_dir_all(installed_libcudf.parent().unwrap()).unwrap();
    fs::create_dir_all(&build_dir).unwrap();
    fs::write(&installed_libcudf, b"installed libcudf").unwrap();
    fs::write(&build_libcudf, b"build-tree libcudf").unwrap();

    let resolved = build_support::cmake::locate_prebuilt_libcudf(Some(&install_dir), Some(&build_dir));

    assert_eq!(resolved.as_deref(), Some(installed_libcudf.as_path()));
    fs::remove_dir_all(temp_dir).unwrap();
}

