#[test]
fn supported_target_os_accepts_linux_only() {
    build_support::toolchain::ensure_supported_target_os("linux").expect("linux target should be accepted");

    let error = build_support::toolchain::ensure_supported_target_os("macos").unwrap_err();
    assert!(error.contains("Linux only"), "unexpected error: {error}");
    assert!(error.contains("macos"), "unexpected error: {error}");

    let error = build_support::toolchain::ensure_supported_target_os("windows").unwrap_err();
    assert!(error.contains("Linux only"), "unexpected error: {error}");
    assert!(error.contains("windows"), "unexpected error: {error}");
}

#[test]
fn canonical_cmake_cache_tracks_matching_build_metadata() {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let temp_dir = std::env::temp_dir().join(format!("cudf-sys-sibling-cache-contract-{unique}"));
    let manifest_dir = temp_dir.join("components/cudf/algeon-cudf-sys");
    let install_dir = temp_dir.join("install");
    let canonical_build = temp_dir.join("target/native/cudf-build");
    fs::create_dir_all(&manifest_dir).unwrap();
    fs::create_dir_all(&install_dir).unwrap();
    fs::create_dir_all(&canonical_build).unwrap();

    assert!(
        build_support::cmake::active_cudf_cmake_cache(&manifest_dir, Some(&install_dir), None).is_none(),
        "install-prefix discovery must ignore an unrelated sibling CMakeCache"
    );
    assert!(
        build_support::cmake::active_cudf_cmake_cache(&manifest_dir, None, None)
            == Some(build_support::cmake::default_cudf_cmake_cache(&manifest_dir)),
        "absent discovery overrides must track the canonical monorepo build tree"
    );
    assert!(
        build_support::cmake::active_cudf_cmake_cache(&manifest_dir, None, Some(&canonical_build),)
            == Some(build_support::cmake::default_cudf_cmake_cache(&manifest_dir)),
        "explicit selection of the canonical build must keep tracking its cache"
    );
    assert_eq!(
        build_support::cmake::active_cudf_cmake_cache(&manifest_dir, None, Some(&temp_dir.join("other-build"))),
        Some(temp_dir.join("other-build/CMakeCache.txt")),
        "a non-default explicit build dir must track only its own cache path"
    );
    assert_eq!(
        build_support::cmake::active_cudf_cmake_cache(
            &manifest_dir,
            Some(&install_dir),
            Some(&temp_dir.join("other-build")),
        ),
        Some(temp_dir.join("other-build/CMakeCache.txt")),
        "explicit build metadata must stay fingerprinted alongside install-prefix discovery"
    );

    fs::remove_dir_all(temp_dir).unwrap();
}

#[test]
fn resolve_compiler_from_env_accepts_absolute_and_basename_toolchains() {
    use std::os::unix::fs::PermissionsExt;

    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let temp_dir = std::env::temp_dir().join(format!("cudf-sys-compiler-contract-{unique}"));
    let compiler = temp_dir.join("cc-wrapper");
    fs::create_dir_all(&temp_dir).unwrap();
    fs::write(&compiler, "#!/bin/sh\nexit 0\n").unwrap();
    let mut permissions = fs::metadata(&compiler).unwrap().permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(&compiler, permissions).unwrap();

    let absolute = build_support::toolchain::resolve_compiler_from_env("CUDF_SYS_TEST_CC_ABS");
    // unset path
    assert_eq!(absolute.unwrap(), None);

    // SAFETY: test process isolates these env vars and restores them below.
    let original_path = std::env::var_os("PATH");
    unsafe {
        std::env::set_var("CUDF_SYS_TEST_CC_ABS", &compiler);
        std::env::set_var("CUDF_SYS_TEST_CC_BASE", "cc-wrapper");
        std::env::set_var("PATH", std::env::join_paths([&temp_dir, Path::new("/usr/bin"), Path::new("/bin")]).unwrap());
    }

    let resolved_abs = build_support::toolchain::resolve_compiler_from_env("CUDF_SYS_TEST_CC_ABS")
        .unwrap()
        .expect("absolute CC override should resolve");
    let resolved_base = build_support::toolchain::resolve_compiler_from_env("CUDF_SYS_TEST_CC_BASE")
        .unwrap()
        .expect("basename CC should resolve through PATH");
    let resolved_default =
        build_support::toolchain::resolve_compiler_from_env_or_name("CUDF_SYS_TEST_CC_DEFAULT", "cc-wrapper")
            .expect("unset CC should resolve the default compiler through PATH");
    assert!(resolved_abs.is_absolute(), "absolute override must stay absolute: {}", resolved_abs.display());
    assert!(resolved_base.is_absolute(), "basename resolution must return absolute path: {}", resolved_base.display());
    assert_eq!(resolved_abs.file_name(), compiler.file_name());
    assert_eq!(resolved_base.file_name(), compiler.file_name());
    assert_eq!(resolved_default, resolved_base);

    unsafe {
        std::env::remove_var("CUDF_SYS_TEST_CC_ABS");
        std::env::remove_var("CUDF_SYS_TEST_CC_BASE");
        match original_path {
            Some(path) => std::env::set_var("PATH", path),
            None => std::env::remove_var("PATH"),
        }
    }

    fs::remove_dir_all(temp_dir).unwrap();
}

#[test]
fn primary_shim_identity_requires_root_runtime_and_linked_shim_to_name_one_prefix() {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let temp_dir = std::env::temp_dir().join(format!("cudf-sys-primary-identity-contract-{unique}"));
    let primary = temp_dir.join("primary");
    let production = primary.join("production-out");

    for prefix in [&primary, &production] {
        fs::create_dir_all(prefix.join("lib")).unwrap();
        fs::create_dir_all(prefix.join("share/cudf_rust")).unwrap();
        fs::write(prefix.join("lib/libcudf_rust.so"), b"shim").unwrap();
        fs::write(
            prefix.join("share/cudf_rust/cargo-link.txt"),
            format!(
                "cargo:rustc-link-search=native={}\ncargo:rustc-link-lib=dylib=cudf_rust\n",
                prefix.join("lib").display()
            ),
        )
        .unwrap();
    }

    let runtime_lib = primary.join("lib/libcudf_rust.so");
    build_support::cmake::verify_primary_shim_identity(&primary, &runtime_lib)
        .expect("consistent root, runtime library, and linked shim must pass");

    // The finding-2 failure mode: runtime metadata names the auxiliary
    // production prefix while the exported root names the primary prefix.
    let error = build_support::cmake::verify_primary_shim_identity(&primary, &production.join("lib/libcudf_rust.so"))
        .expect_err("auxiliary-prefix runtime library must violate the identity contract");
    assert!(error.contains("primary install prefix"), "unexpected error: {error}");

    let empty_root = temp_dir.join("empty-root");
    fs::create_dir_all(&empty_root).unwrap();
    let error = build_support::cmake::verify_primary_shim_identity(&empty_root, &runtime_lib)
        .expect_err("a root without the primary install must violate the identity contract");
    assert!(error.contains("cargo link manifest"), "unexpected error: {error}");

    fs::remove_dir_all(temp_dir).unwrap();
}

/// Minimal ELF64 shared object with the given `DT_NEEDED` entries. Layout:
/// ELF header, PT_LOAD covering the whole file (vaddr == file offset),
/// PT_DYNAMIC, the dynamic section, then the dynamic string table.
fn synthetic_elf64_with_dt_needed(needed: &[&str]) -> Vec<u8> {
    const EHDR: usize = 64;
    const PHDR: usize = 56;

    let mut strtab = vec![0u8];
    let mut name_offsets = Vec::new();
    for name in needed {
        name_offsets.push(strtab.len() as u64);
        strtab.extend_from_slice(name.as_bytes());
        strtab.push(0);
    }
    let dynamic_offset = EHDR + 2 * PHDR;
    let entries = 2 + needed.len() + 1; // DT_STRTAB + DT_STRSZ + DT_NEEDEDs + DT_NULL
    let dynamic_size = entries * 16;
    let strtab_offset = dynamic_offset + dynamic_size;
    let total = strtab_offset + strtab.len();

    let mut bytes = vec![0u8; total];
    bytes[0..4].copy_from_slice(&[0x7f, b'E', b'L', b'F']);
    bytes[4] = 2; // ELFCLASS64
    bytes[5] = 1; // ELFDATA2LSB
    bytes[6] = 1; // EV_CURRENT
    bytes[16..18].copy_from_slice(&3u16.to_le_bytes()); // ET_DYN
    bytes[18..20].copy_from_slice(&62u16.to_le_bytes()); // EM_X86_64
    bytes[20..24].copy_from_slice(&1u32.to_le_bytes()); // e_version
    bytes[32..40].copy_from_slice(&(EHDR as u64).to_le_bytes()); // e_phoff
    bytes[52..54].copy_from_slice(&(EHDR as u16).to_le_bytes()); // e_ehsize
    bytes[54..56].copy_from_slice(&(PHDR as u16).to_le_bytes()); // e_phentsize
    bytes[56..58].copy_from_slice(&2u16.to_le_bytes()); // e_phnum

    let load = &mut bytes[EHDR..EHDR + PHDR];
    load[0..4].copy_from_slice(&1u32.to_le_bytes()); // PT_LOAD
    load[4..8].copy_from_slice(&5u32.to_le_bytes()); // PF_R | PF_X
    load[32..40].copy_from_slice(&(total as u64).to_le_bytes()); // p_filesz
    load[40..48].copy_from_slice(&(total as u64).to_le_bytes()); // p_memsz

    let dynamic = &mut bytes[EHDR + PHDR..EHDR + 2 * PHDR];
    dynamic[0..4].copy_from_slice(&2u32.to_le_bytes()); // PT_DYNAMIC
    dynamic[8..16].copy_from_slice(&(dynamic_offset as u64).to_le_bytes()); // p_offset
    dynamic[16..24].copy_from_slice(&(dynamic_offset as u64).to_le_bytes()); // p_vaddr
    dynamic[32..40].copy_from_slice(&(dynamic_size as u64).to_le_bytes()); // p_filesz

    let tags: Vec<(i64, u64)> = [(5, strtab_offset as u64), (10, strtab.len() as u64)]
        .into_iter()
        .chain(name_offsets.iter().map(|offset| (1, *offset)))
        .chain([(0, 0)])
        .collect();
    for (index, (tag, value)) in tags.iter().enumerate() {
        let at = dynamic_offset + index * 16;
        bytes[at..at + 8].copy_from_slice(&tag.to_le_bytes());
        bytes[at + 8..at + 16].copy_from_slice(&value.to_le_bytes());
    }
    bytes[strtab_offset..].copy_from_slice(&strtab);
    bytes
}

fn elf_contract_temp_dir(label: &str) -> PathBuf {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let dir = std::env::temp_dir().join(format!("cudf-sys-{label}-{unique}"));
    fs::create_dir_all(&dir).unwrap();
    dir
}

#[test]
fn elf_dt_needed_reads_dynamic_dependencies_in_order() {
    let dir = elf_contract_temp_dir("elf-dt-needed");
    let library = dir.join("libfake.so");
    fs::write(&library, synthetic_elf64_with_dt_needed(&["libfoo.so", "libbar.so"])).unwrap();

    let dependencies = build_support::elf::elf_dt_needed(&library).unwrap();

    assert_eq!(dependencies, vec!["libfoo.so".to_string(), "libbar.so".to_string()]);
    fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn elf_dt_needed_is_empty_without_a_dynamic_section() {
    let dir = elf_contract_temp_dir("elf-no-dynamic");
    let library = dir.join("libfake.so");

    let mut no_program_headers = synthetic_elf64_with_dt_needed(&["libfoo.so"]);
    no_program_headers[56..58].copy_from_slice(&0u16.to_le_bytes()); // e_phnum = 0
    fs::write(&library, &no_program_headers).unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap().is_empty());

    let mut no_dynamic_segment = synthetic_elf64_with_dt_needed(&["libfoo.so"]);
    no_dynamic_segment[64 + 56..64 + 60].copy_from_slice(&4u32.to_le_bytes()); // PT_DYNAMIC -> PT_NOTE
    fs::write(&library, &no_dynamic_segment).unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap().is_empty());

    fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn elf_dt_needed_rejects_non_elf_and_unsupported_layouts() {
    let dir = elf_contract_temp_dir("elf-rejects");
    let library = dir.join("libfake.so");

    fs::write(&library, b"not an elf file at all, long enough to pass the header read.........").unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap_err().contains("not an ELF file"));

    fs::write(&library, b"\x7fELF").unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap_err().contains("failed to read ELF header"));

    let mut thirty_two_bit = synthetic_elf64_with_dt_needed(&[]);
    thirty_two_bit[4] = 1; // ELFCLASS32
    fs::write(&library, &thirty_two_bit).unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap_err().contains("not a 64-bit ELF file"));

    let mut big_endian = synthetic_elf64_with_dt_needed(&[]);
    big_endian[5] = 2; // ELFDATA2MSB
    fs::write(&library, &big_endian).unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap_err().contains("not a little-endian ELF file"));

    let mut relocatable = synthetic_elf64_with_dt_needed(&[]);
    relocatable[16..18].copy_from_slice(&1u16.to_le_bytes()); // ET_REL
    fs::write(&library, &relocatable).unwrap();
    assert!(build_support::elf::elf_dt_needed(&library).unwrap_err().contains("unsupported ELF type"));

    fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn optional_runtime_dep_classification_requires_real_linkage() {
    let dir = elf_contract_temp_dir("logger-classification");
    let candidate = dir.join("librapids_logger.so");
    fs::write(&candidate, b"shared logger candidate").unwrap();
    let linked_consumer = dir.join("librmm.so");
    fs::write(&linked_consumer, synthetic_elf64_with_dt_needed(&["libcudart.so", "librapids_logger.so"])).unwrap();
    let absorbed_consumer = dir.join("libcudf.so");
    fs::write(&absorbed_consumer, synthetic_elf64_with_dt_needed(&["libcudart.so"])).unwrap();

    assert_eq!(
        build_support::elf::classify_optional_runtime_dep(
            None,
            std::slice::from_ref(&linked_consumer),
            "librapids_logger.so"
        )
        .unwrap(),
        build_support::elf::OptionalRuntimeDepLinkage::Absorbed,
        "no candidate must classify as absorbed"
    );
    assert_eq!(
        build_support::elf::classify_optional_runtime_dep(
            Some(candidate.clone()),
            std::slice::from_ref(&linked_consumer),
            "librapids_logger.so"
        )
        .unwrap(),
        build_support::elf::OptionalRuntimeDepLinkage::Shared(candidate.clone()),
        "a consumer with a DT_NEEDED entry makes the candidate genuinely shared"
    );
    assert_eq!(
        build_support::elf::classify_optional_runtime_dep(
            Some(candidate.clone()),
            std::slice::from_ref(&absorbed_consumer),
            "librapids_logger.so"
        )
        .unwrap(),
        build_support::elf::OptionalRuntimeDepLinkage::StaleSharedArtifact(candidate.clone()),
        "a candidate no consumer links is a stale artifact"
    );
    assert_eq!(
        build_support::elf::classify_optional_runtime_dep(
            Some(candidate.clone()),
            &[absorbed_consumer, linked_consumer],
            "librapids_logger.so"
        )
        .unwrap(),
        build_support::elf::OptionalRuntimeDepLinkage::Shared(candidate.clone()),
        "any single linking consumer is sufficient evidence"
    );
    let missing_consumer = dir.join("missing.so");
    assert_eq!(
        build_support::elf::classify_optional_runtime_dep(
            Some(candidate.clone()),
            &[missing_consumer],
            "librapids_logger.so"
        )
        .unwrap(),
        build_support::elf::OptionalRuntimeDepLinkage::Shared(candidate),
        "without readable consumers the historical presence-based classification is preserved"
    );

    fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn cmake_discovery_helper_collects_package_prefixes_after_install_guard_matches() {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let temp_dir = std::env::temp_dir().join(format!("cudf-sys-cmake-discovery-contract-{unique}"));
    let install_dir = temp_dir.join("install");
    let other_install_dir = temp_dir.join("other-install");
    let build_dir = temp_dir.join("build");
    let rapids_logger_dir = build_dir.join("_deps/rapids_logger-build");
    let nvtx_dir = build_dir.join("_deps/nvtx3-build");
    let empty_dir = build_dir.join("_deps/empty-build");
    let cache_path = build_dir.join("CMakeCache.txt");
    let script_path = temp_dir.join("check.cmake");
    let discovery_helper = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("native/cmake/cudf-discovery.cmake");

    fs::create_dir_all(&install_dir).unwrap();
    fs::create_dir_all(&other_install_dir).unwrap();
    fs::create_dir_all(&rapids_logger_dir).unwrap();
    fs::create_dir_all(&nvtx_dir).unwrap();
    fs::create_dir_all(&empty_dir).unwrap();
    fs::write(rapids_logger_dir.join("rapids_logger-config.cmake"), "").unwrap();
    fs::write(nvtx_dir.join("nvtx3Config.cmake"), "").unwrap();
    fs::write(
        &cache_path,
        format!(
            "\
CMAKE_INSTALL_PREFIX:PATH={}
RAPIDS_LOGGER_BINARY_DIR:STATIC={}
NVTX3_BINARY_DIR:STATIC={}
EMPTY_BINARY_DIR:STATIC={}
MISSING_BINARY_DIR:STATIC={}
",
            install_dir.display(),
            rapids_logger_dir.display(),
            nvtx_dir.display(),
            empty_dir.display(),
            build_dir.join("_deps/missing-build").display()
        ),
    )
    .unwrap();
    fs::write(
        &script_path,
        format!(
            "\
include(\"{helper}\")
cudf_rust_build_dir_metadata_matches_install(\"{build}\" \"{install}\" OFF use_matching)
if(NOT use_matching)
  message(FATAL_ERROR \"expected matching install prefix to enable build metadata\")
endif()
cudf_rust_build_dir_metadata_matches_install(\"{build}\" \"{other_install}\" OFF use_mismatch)
if(use_mismatch)
  message(FATAL_ERROR \"expected mismatched install prefix to disable build metadata\")
endif()
cudf_rust_collect_package_prefixes(\"{cache}\" prefixes)
set(expected \"{rapids_logger};{nvtx}\")
if(NOT prefixes STREQUAL expected)
  message(FATAL_ERROR \"unexpected package prefixes: ${{prefixes}}\")
endif()
",
            helper = discovery_helper.display(),
            build = build_dir.display(),
            install = install_dir.display(),
            other_install = other_install_dir.display(),
            cache = cache_path.display(),
            rapids_logger = rapids_logger_dir.display(),
            nvtx = nvtx_dir.display()
        ),
    )
    .unwrap();

    let output = Command::new("cmake").arg("-P").arg(&script_path).output().unwrap();
    assert!(
        output.status.success(),
        "cmake discovery contract failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    fs::remove_dir_all(&temp_dir).unwrap();
}

#[test]
fn clang_lint_file_matcher_accepts_supported_c_family_sources_only() {
    for path in [
        "native/src/error.cpp",
        "native/src/c_header_smoke.c",
        "native/include/cudf_rust/error.h",
        "native/src/handle_access.hpp",
    ] {
        assert!(build_support::lint::is_clang_lintable_path(Path::new(path)), "expected {path} to be clang-lintable");
    }

    for path in [
        "native/cmake/cargo-link.txt.in",
        "native/src/owning_handle_fwd.hpp.in",
        "native/src/README.md",
        "native/src/not_a_source.rs",
    ] {
        assert!(
            !build_support::lint::is_clang_lintable_path(Path::new(path)),
            "expected {path} to be excluded from clang linting"
        );
    }
}

#[test]
fn collect_native_clang_lint_files_is_scoped_to_src_and_include() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let lint_files = build_support::lint::collect_native_clang_lint_files(manifest_dir).unwrap();

    assert!(!lint_files.is_empty(), "expected cudf-sys/native to expose at least one clang-lintable file");
    assert!(
        lint_files.iter().all(|path| path.starts_with(manifest_dir.join("native/src"))
            || path.starts_with(manifest_dir.join("native/include"))),
        "expected clang lint files to stay within cudf-sys/native/src and cudf-sys/native/include: {lint_files:?}"
    );
    assert!(
        lint_files.iter().all(|path| build_support::lint::is_clang_lintable_path(path)),
        "expected every collected file to satisfy the lintable-path predicate: {lint_files:?}"
    );
    let upstream_native = manifest_dir.join("../cudf");
    assert!(
        lint_files.iter().all(|path| !path.starts_with(&upstream_native)),
        "expected upstream cudf files to stay out of cudf-sys lint scope: {lint_files:?}"
    );

    // The collector appends `native/src` and `native/include` to the crate
    // manifest directory itself, so handing it the native directory
    // double-prefixes the lookup and must be rejected.
    let error = build_support::lint::collect_native_clang_lint_files(&build_support::lint::native_dir(manifest_dir))
        .unwrap_err();
    assert!(
        error.contains("failed to read clang lint directory"),
        "expected the native directory to be rejected as a lint root: {error}"
    );
}

#[test]
fn find_executable_in_path_reports_missing_binary() {
    let error = build_support::toolchain::find_executable_in_path(
        "clang-format",
        std::env::join_paths(["/definitely/missing"]).unwrap(),
    )
    .unwrap_err();
    assert!(error.contains("clang-format"), "unexpected error: {error}");
    assert!(error.contains("PATH"), "unexpected error: {error}");
}

#[test]
fn find_executable_in_path_finds_executable_binaries() {
    {
        use std::os::unix::fs::PermissionsExt;

        let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let temp_dir = std::env::temp_dir().join(format!("cudf-sys-build-tool-contract-{unique}"));
        let executable_path = temp_dir.join("clang-tidy");

        fs::create_dir_all(&temp_dir).unwrap();
        fs::write(&executable_path, "#!/bin/sh\nexit 0\n").unwrap();
        let mut permissions = fs::metadata(&executable_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&executable_path, permissions).unwrap();

        let discovered =
            build_support::toolchain::find_executable_in_path("clang-tidy", std::env::join_paths([&temp_dir]).unwrap())
                .unwrap();

        assert_eq!(discovered, executable_path);

        fs::remove_file(&executable_path).unwrap();
        fs::remove_dir_all(&temp_dir).unwrap();
    }
}
